for s in SEC: os.makedirs(os.path.join(P, s), exist_ok=True)
manifest = []; missing = []
def put(src, sec, name=None):
    if not os.path.exists(src): missing.append(src); return
    dst = os.path.join(P, sec, name or os.path.basename(src)); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(src, dst); manifest.append((sec + '/' + (name or os.path.basename(src)), os.path.relpath(src, ROOT)))
def putdir(srcdir, sec, sub, pats=('*',)):
    for pat in pats:
        for f in glob.glob(os.path.join(srcdir, pat)):
            if os.path.isfile(f): put(f, sec, sub + '/' + os.path.basename(f))
